import assert from 'node:assert/strict';
import {mkdirSync,readFileSync,writeFileSync,appendFileSync,existsSync} from 'node:fs';
import {spawn} from 'node:child_process';
import {createHash} from 'node:crypto';
const root='F:/VisibleMedicine/staging/20261022-viewer-assurance-candidate',website=root+'/website',step=root+'/historical-cohort';
assert(!existsSync(step));mkdirSync(step);
const tests=['tests/historical-review-ae84-preservation.test.mjs','tests/colic-current-admission.test.mjs','tests/clinical-review-desktop-layout.test.mjs','tests/expanded-viewer-type-preservation.test.mjs','tests/atlas-cerebral-schema-preservation.test.mjs','tests/clinical-review-cervical-disc-tour-preservation.test.mjs'];
